

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .reasoning_body_content_item import ReasoningBodyContentItem
from .reasoning_body_summary_item import ReasoningBodySummaryItem


class ReasoningBody(UniversalBaseModel):
    """
    A reasoning item that was generated by the model.
    """

    id: str = pydantic.Field()
    """
    The unique ID of the reasoning item.
    """

    content: typing.Optional[typing.List[ReasoningBodyContentItem]] = pydantic.Field(default=None)
    """
    The reasoning content that was generated.
    """

    summary: typing.List[ReasoningBodySummaryItem] = pydantic.Field()
    """
    The reasoning summary content that was generated.
    """

    encrypted_content: typing.Optional[str] = pydantic.Field(default=None)
    """
    The encrypted reasoning content that was generated.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
